// CORTAFUEGOS ANTI-AVALANCHA
// Como maximo MAX_AVISOS mensajes cada VENTANA_MIN minutos, y nunca dos veces
// el mismo error dentro de esa ventana. Todo queda registrado en Supabase
// aunque no se envie, asi que no se pierde informacion.
const VENTANA_MIN = 15;
const MAX_AVISOS  = 5;
const TELEFONO_AVISO = '34640575291';

const d  = $input.first().json || {};
const wf = d.workflow || {};
const ex = d.execution || {};
const err = ex.error || {};

const nombreWf = wf.name || wf.id || 'desconocido';

// Nunca avisar de un fallo del propio workflow de avisos: seria un bucle.
if (/Avisos de error/i.test(nombreWf)) return [];

const corta = (v, max) => {
  const s = (v === null || v === undefined) ? '' : v.toString().replace(/\s+/g, ' ').trim();
  return s.length > max ? s.slice(0, max - 3) + '...' : s;
};

const mensajeError = corta(err.message || err.description || 'Error sin mensaje', 400);
const nodoFallo = ex.lastNodeExecuted || 'desconocido';
const huella = corta([nombreWf, nodoFallo, mensajeError].join('|'), 200);

// Cuantos avisos se han enviado ya en la ventana
const recientes = $('Cargar avisos recientes').all()
  .map(i => i.json || {})
  .filter(r => r && r.id);

const yaAvisadoIgual = recientes.some(r => r.huella === huella);
const topeAlcanzado  = recientes.length >= MAX_AVISOS;
const debeAvisar     = !yaAvisadoIgual && !topeAlcanzado;
const esElUltimo     = debeAvisar && recientes.length === MAX_AVISOS - 1;

const TZ = 'Europe/Madrid';
const ahora = new Intl.DateTimeFormat('es-ES', {
  timeZone: TZ,
  day: '2-digit', month: '2-digit', year: 'numeric',
  hour: '2-digit', minute: '2-digit', hour12: false
}).format(new Date()).replace(',', '');

const lineas = [
  '🚨 FALLO EN UNA AUTOMATIZACION',
  '',
  'Workflow: ' + nombreWf,
  'Nodo: ' + nodoFallo,
  'Cuando: ' + ahora,
  '',
  'Error: ' + mensajeError
];

if (ex.url) {
  lineas.push('');
  lineas.push('Ver ejecucion: ' + ex.url);
}

if (esElUltimo) {
  lineas.push('');
  lineas.push('⚠️ Este es el aviso ' + MAX_AVISOS + ' de ' + MAX_AVISOS + ' en ' + VENTANA_MIN + ' minutos.');
  lineas.push('Silencio los siguientes para no inundarte. Se siguen guardando');
  lineas.push('en la tabla avisos_error de Supabase.');
}

return [{
  json: {
    telefono_aviso: TELEFONO_AVISO,
    workflow_nombre: nombreWf,
    nodo: nodoFallo,
    error: mensajeError,
    huella,
    debe_avisar: debeAvisar,
    motivo_silencio: yaAvisadoIgual ? 'error repetido' : (topeAlcanzado ? 'tope alcanzado' : ''),
    respuesta: lineas.join('\n')
  }
}];
